import math

def find_Index(n):
    if n == 1:
        return 1
    low = 1
    high = 10**n
    while low <= high:
        mid = (low + high) // 2
        T = mid * (mid + 1) // 2
        if T >= 10**(n-1):
            high = mid - 1
        else:
            low = mid + 1
    return low

